import { randomUUID } from "node:crypto";

let source = "";
for await (const chunk of process.stdin) source += chunk;
const input = JSON.parse(source || "{}");

const documentId = input.documentId ?? randomUUID();
const timestamp = input.timestamp ?? new Date().toISOString();
const headers = { "content-type": "application/json" };
const vendorStatus = input.vendorStatus ?? 200;
const key = input.idempotencyKey;

function result(status, body, extra = {}) {
  return {
    http: { status, headers, body },
    database: { rows: [], transaction: { committed: false, rolledBack: false }, ...extra.database },
    messages: [],
    outbound: [],
    ordering: [],
    failures: [],
    retryability: false,
    ...extra.rest,
  };
}

function fail(status, code, outbound, ordering, retryable) {
  const out = result(status, { error: code, retryable }, {
    database: { transaction: { committed: false, rolledBack: true } },
    rest: { outbound, ordering, failures: [{ code, status, vendorStatus }], retryability: retryable },
  });
  out.database.transaction.rolledBack = false;
  return out;
}

const body = { id: documentId, title: input.title, createdAt: timestamp };
let out;

const prior = input.existing ?? input.replay ?? input.priorRequests?.[key];
if (key !== undefined && prior) {
  // Idempotent replay: same response, no new side effects.
  const orig = typeof prior === "object" ? prior : {};
  const replayBody = orig.body ?? { id: orig.id ?? documentId, title: orig.title ?? input.title, createdAt: orig.createdAt ?? timestamp };
  out = result(orig.status ?? 201, replayBody, {
    database: { rows: [{ ...replayBody }], transaction: { committed: false, rolledBack: false } },
    rest: { ordering: ["replay"] },
  });
  out.http.headers = { ...headers, "idempotent-replay": "true" };
} else if (typeof input.title !== "string" || input.title.trim() === "") {
  out = result(400, { error: "validation_failed", field: "title" }, {
    rest: { failures: [{ code: "validation_failed", status: 400 }] },
  });
} else {
  const outbound = [
    { service: "vendor", operation: "authorize", documentId, timestamp },
    { service: "vendor", operation: "index", documentId, timestamp },
  ];
  if (vendorStatus >= 200 && vendorStatus < 300) {
    out = result(201, body, {
      database: {
        rows: [{ id: documentId, title: input.title, createdAt: timestamp, idempotencyKey: key }],
        transaction: { committed: true, rolledBack: false },
      },
      rest: {
        messages: [{ type: "document.created", documentId, title: input.title, timestamp }],
        outbound,
        ordering: ["vendor.authorize", "vendor.index", "database.commit", "event.emit"],
      },
    });
    out.http.headers = headers;
  } else {
    const retryable = vendorStatus === 408 || vendorStatus === 429 || vendorStatus >= 500;
    const status = retryable ? 503 : 502;
    out = fail(status, "vendor_failure", outbound.slice(0, 1), ["vendor.authorize"], retryable);
  }
}

console.log(JSON.stringify(out));

